'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[[12,1,16,2],[16,2,20,3],[20,1,24,3],[24,2,12,2],[16,1,24,2],[20,2,16,3]];
let variant=OrionProgress.variant('pulleys'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,sections=1,pull=0,solved=false,hintDepth=0,state='ready',saveFailed=false,drag=null;
function challenge(v=variant,s=stage){const [w,h,w2,h2]=journeys[v];return {weight:s===2?w2:w,height:s===2?h2:h,limit:s===0?w:(s===2?w2:w)/2};}
function force(n=sections,q=challenge()){return q.weight/n;}
function rise(){return pull/sections;}
function resetTrial(){sections=1;pull=0;solved=false;hintDepth=0;state='ready';saveFailed=false;drag=null;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('pulleys')){variant=v;stage=0;resetTrial();}
function choose(n){if(solved||drag||![1,2].includes(n)||stage===0&&n!==1)return;sections=n;pull=0;state='ready';render();}
function setPull(v){if(solved||!Number.isFinite(v)||v<0||v>sections*3||v*2!==Math.round(v*2))return;if(force()>challenge().limit){pull=0;state='heavy';}else{pull=v;state='ready';}render();}
function check(){if(solved||drag)return;if(force()>challenge().limit)state='heavy';else if(rise()!==challenge().height)state=rise()<challenge().height?'short':'high';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('uplift');}render();if(solved&&stage<2)$('next').focus();}
function dragStart(e){if(solved||drag||e.button!==undefined&&e.button!==0)return;const rect=$('crane').querySelector('svg').getBoundingClientRect(),scale=Math.min(rect.width/420,rect.height/300),ox=rect.left+(rect.width-420*scale)/2,oy=rect.top+(rect.height-300*scale)/2,x=(e.clientX-ox)/scale,y=(e.clientY-oy)/scale;if(Math.abs(x-258)>Math.max(30,22/scale)||Math.abs(y-(90+pull*20))>Math.max(28,22/scale))return;drag={id:e.pointerId,startY:e.clientY,original:pull,scale};$('crane').setPointerCapture?.(e.pointerId);}
function dragMove(e){if(!drag||drag.id!==e.pointerId)return;setPull(Math.max(0,Math.min(sections*3,Math.round((drag.original+(e.clientY-drag.startY)/(20*drag.scale))*2)/2)));}
function dragEnd(e,cancel=false){if(!drag||drag.id!==e.pointerId)return;const old=drag.original;if(!cancel)dragMove(e);drag=null;if(cancel){pull=old;state='ready';render();}}
function hints(){const q=challenge();return [t('Move the gold handle down. Compare rope travel with how far the chest rises. The dashed line is your landing height.','向下移動金色把手。比較拉繩距離和寶箱升高的距離。虛線就是目標高度。'),t('A fixed wheel changes direction. Two sections supporting a movable wheel share the load: less force, more rope to pull.','定滑輪改變方向。兩段繩支撐動滑輪時，會分擔負重：拉力較小，但要拉更多繩。'),t(`Use ${stage===0?'the fixed crane':'the movable crane'} and pull ${q.height*(stage===0?1:2)} m of rope to lift ${q.height} m.`,`用${stage===0?'定':'動'}滑輪吊機，拉 ${q.height*(stage===0?1:2)} 米繩，升高 ${q.height} 米。`)];}
function wheel(x,y){return `<circle cx="${x}" cy="${y}" r="16" fill="#5c7275" stroke="#e8c780" stroke-width="3"/><circle cx="${x}" cy="${y}" r="5" fill="#e8c780"/>`;}
function render(){const q=challenge(),complete=solved&&stage===2,progress=stage+Number(solved),y=200-rise()*35,cx=sections===1?226:210,hy=90+pull*20;window.OrionDiscovery?.update(complete);document.title=t('The Sky Crane · Orion','雲端吊塔 · Orion');$('stageTitle').textContent=t(`Lift ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 次升降 · 第 ${variant+1} 組`);$('sceneStatus').textContent=t(`Tower seals · ${progress} / 3`,`吊塔封印 · ${progress} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<progress?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
$('fixed').textContent=t('① Fixed wheel','① 定滑輪');$('moving').textContent=t('② Movable + fixed','② 動滑輪＋定滑輪');for(const [id,n] of [['fixed',1],['moving',2]]){$(id).setAttribute('aria-pressed',String(sections===n));$(id).disabled=solved||stage===0&&n===2;}
const rope=sections===1?`M226 ${y+20}V50 A16 16 0 0 1 258 50 V${hy}`:`M194 24V${y} A16 16 0 0 0 226 ${y} V50 A16 16 0 0 1 258 50 V${hy}`;
$('crane').innerHTML=`<svg viewBox="0 0 420 300" aria-hidden="true"><path d="M100 24H300" stroke="#879d9a" stroke-width="10"/><path d="M242 24V34" stroke="#bcc6bc" stroke-width="4"/>${wheel(242,50)}${sections===2?wheel(210,y):''}<path d="${rope}" stroke="#f6d891" stroke-width="4" fill="none"/>${sections===2?`<path d="M210 ${y+16}V${y+22}" stroke="#bcc6bc" stroke-width="4"/>`:''}<rect x="${cx-28}" y="${y+20}" width="56" height="35" rx="5" fill="#966b38" stroke="#f5d28b" stroke-width="2"/><path d="M${cx-28} ${y+31}h56" stroke="#f5d28b"/><rect x="${cx-4}" y="${y+29}" width="8" height="12" fill="#f5d28b"/><path d="M100 255H300" stroke="#688082" stroke-width="3"/><path d="M95 ${255-q.height*35}H305" stroke="#8fe4d7" stroke-width="2" stroke-dasharray="6 5"/><text x="20" y="${252-q.height*35}" fill="#b8f0dc" font-size="19">${q.height} m ↑</text><rect x="236" y="${hy-12}" width="44" height="24" rx="10" fill="#f3ce7c" stroke="#fff1c3" stroke-width="2"/><text x="298" y="${hy+5}" fill="#f3ce7c" font-size="19">↓ ${t('Pull','拉繩')}</text><text x="210" y="285" text-anchor="middle" fill="#d3e2dc" font-size="19">${t(`${sections} supporting rope section${sections===1?'':'s'}`,`${sections} 段繩支撐負重`)}</text></svg>`;
$('crane').setAttribute('aria-label',t(`Crane model: ${sections} supporting sections. Chest rises ${rise()} m. Gold rope handle: drag down to pull; the slider is an alternative.`,`吊機模型：${sections} 段支撐繩。寶箱升高 ${rise()} 米。向下拖金色把手拉繩，亦可用滑桿。`));$('pull').value=pull;$('pull').max=sections*3;$('pull').disabled=solved;$('pull').setAttribute('aria-valuetext',t(`${pull} metres of rope pulled`, `已拉 ${pull} 米繩`));$('less').disabled=solved||pull===0;$('more').disabled=solved||pull===sections*3;
$('goal').textContent=t(`Lift a ${q.weight} N chest by ${q.height} m. Keeper’s pull limit: ${q.limit} N.${stage===0?' Start with the fixed wheel.':''}`,`把 ${q.weight} N 寶箱升高 ${q.height} 米。守塔人的拉力上限：${q.limit} N。${stage===0?'先用定滑輪。':''}`);
$('reading').innerHTML=`<strong>${t('Required pull','所需拉力')}: ${force()} N / ${q.limit} N</strong>${t('Rope pulled','已拉繩長')}: ${pull} m · ${t('Chest rise','寶箱升高')}: ${rise()} m`;
$('evidence').textContent=stage===1?t(`Same chest and height as lift 1. Previously: ${q.weight} N and ${q.height} m of rope. Compare the new readings.`,`與第 1 次相同負重和高度。之前：${q.weight} N 拉力、${q.height} 米繩。比較新讀數。`):t('Match the landing mark without exceeding the keeper’s pull limit.','不要超過守塔人的拉力上限，把寶箱升到平台標記。');
const messages={ready:['Choose, pull, and watch the chest. Record when it reaches the mark.','選擇、拉繩，觀察寶箱。到達標記時記錄。'],heavy:['This needs more force than the keeper can pull. Try a different crane.','所需拉力超過守塔人的上限。試試另一種吊機。'],short:['Not high enough yet. Pull some more rope.','還不夠高。再拉一些繩。'],high:['Above the landing mark. Let some rope back.','高過平台標記了。放回一些繩。'],success:['The chest reaches its landing. A tower seal shines!','寶箱到達平台，吊塔封印亮起了！']};$('feedback').textContent=t(...messages[state]);
$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('uplift')?t('Uplift Sigil saved in your collection.','升力符印已存入收藏。'):'';}
$('fixed').onclick=()=>choose(1);$('moving').onclick=()=>choose(2);$('pull').oninput=()=>setPull(Number($('pull').value));$('less').onclick=()=>setPull(pull-.5);$('more').onclick=()=>setPull(pull+.5);$('crane').onpointerdown=dragStart;$('crane').onpointermove=dragMove;$('crane').onpointerup=e=>dragEnd(e);$('crane').onpointercancel=e=>dragEnd(e,true);$('crane').onlostpointercapture=e=>dragEnd(e,true);
$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('fixed').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('pulleys',variant);observedVariant=OrionProgress.variant('pulleys');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('uplift');render();};
function syncProgress(){const v=OrionProgress.variant('pulleys'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('uplift')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);window.addEventListener('pagehide',()=>{if(drag){pull=drag.original;drag=null;}});resetMission();OrionI18n.apply();
